import React, { useState, useEffect } from 'react';
import BotCollection from './components/BotCollection';
import BotArmy from './components/BotArmy';
import BotSpecs from './components/'
import SortBar from './components/SortBar';
import FilterBar from './components/FilterBar';
import './App.css';

function App() {
  const [bots, setBots] = useState([]);
  const [army, setArmy] = useState([]);
  const [selectedBot, setSelectedBot] = useState(null);
  const [sortBy, setSortBy] = useState('health');
  const [filters, setFilters] = useState({
    Support: false,
    Medic: false,
    Assault: false,
    Defender: false,
    Captain: false,
    Witch: false
  });

  useEffect(() => {
    fetch('http://localhost:8001/bots')
      .then(res => res.json())
      .then(data => setBots(data))
      .catch(err => console.error('Error fetching bots:', err));
  }, []);

  const addToArmy = (bot) => {
    if (!army.some(b => b.id === bot.id) && !army.some(b => b.bot_class === bot.bot_class)) {
      setArmy([...army, bot]);
    }
  };

  const releaseFromArmy = (bot) => {
    setArmy(army.filter(b => b.id !== bot.id));
  };

  const dischargeBot = (bot) => {
    fetch(`http://localhost:8001/bots/${bot.id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setBots(bots.filter(b => b.id !== bot.id));
      setArmy(army.filter(b => b.id !== bot.id));
    })
    .catch(err => console.error('Error deleting bot:', err));
  };

  const handleSort = (criteria) => {
    setSortBy(criteria);
  };

  const handleFilter = (botClass) => {
    setFilters({
      ...filters,
      [botClass]: !filters[botClass]
    });
  };

  const filteredBots = bots.filter(bot => {
    if (Object.values(filters).every(val => !val)) return true;
    return filters[bot.bot_class];
  });

  const sortedBots = [...filteredBots].sort((a, b) => b[sortBy] - a[sortBy]);

  return (
    <div className="App">
      <h1>Bot Battlr</h1>
      <div className="controls">
        <SortBar onSort={handleSort} />
        <FilterBar onFilter={handleFilter} filters={filters} />
      </div>
      <div className="container">
        {selectedBot ? (
          <BotSpecs 
            bot={selectedBot} 
            onBack={() => setSelectedBot(null)}
            onEnlist={() => {
              addToArmy(selectedBot);
              setSelectedBot(null);
            }}
          />
        ) : (
          <BotCollection 
            bots={sortedBots} 
            onBotSelect={setSelectedBot}
            onDischarge={dischargeBot}
          />
        )}
        <BotArmy 
          army={army} 
          onRelease={releaseFromArmy} 
          onDischarge={dischargeBot}
        />
      </div>
    </div>
  );
}

export default App;
